package com.sumedha.commerce.product.repository; import com.sumedha.commerce.product.entity.Product; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.JpaSpecificationExecutor; import java.util.*; public interface ProductRepository extends JpaRepository<Product,UUID>,JpaSpecificationExecutor<Product>{Optional<Product> findBySku(String sku);Optional<Product> findBySlug(String slug);boolean existsBySku(String sku);boolean existsBySlug(String slug);boolean existsByCategoryId(UUID categoryId);boolean existsByBrandId(UUID brandId);boolean existsBySlugAndIdNot(String slug,UUID id);}
